  rlvTop2Vec(h1, nH1, h2, nH2, sgn * invSqrt3, d);
  rlvTop2Vec(h1, nH1, h2, nH2, flipMin * invSqrt3, d);
  rlvTop2Vec(h1, nH1, h2, nH2, vec3(sgn.x * c, 0.0, sgn.z * e), d);
  rlvTop2Vec(h1, nH1, h2, nH2, vec3(-sgn.x * c, 0.0, sgn.z * e), d);
  rlvTop2Vec(h1, nH1, h2, nH2, vec3(sgn.x * e, sgn.y * c, 0.0), d);
  rlvTop2Vec(h1, nH1, h2, nH2, vec3(sgn.x * e, -sgn.y * c, 0.0), d);
  rlvTop2Vec(h1, nH1, h2, nH2, vec3(0.0, sgn.y * e, sgn.z * c), d);
